import React, { useState, useEffect, useRef } from 'react';
import './App.css';

function App() {
  // Data from backend
  const [customers, setCustomers] = useState([]);
  const [storages, setStorages] = useState([]);

  // For live suggestions
  const [searchTerms, setSearchTerms] = useState([]); // [{customer: '', storage: ''}]
  const [customerSuggestions, setCustomerSuggestions] = useState([]); // [[...], ...]
  const [storageSuggestions, setStorageSuggestions] = useState([]); // [[...], ...]

  // Table rows
  const [rows, setRows] = useState([]); // [{id, customerId, customerName, category, weight, storageId, storageName}]

  // Example categories (replace with your own logic if needed)
  const [categories, setCatalogs] = useState([]);

  // For closing suggestions
  const suggestionRefs = useRef([]);

  // Fetch customers and storages
  useEffect(() => {
    fetch("http://127.0.0.1:5000/customers")
      .then(res => res.json())
      .then(data => setCustomers(data.customers.map(c => ({
        id: c.CustomerID,
        name: c.CustomerName,
        address: c.CustomerAddress,
        location: [c.CustomerLat, c.CustomerLong],
      }))))
      .catch(console.error);

    fetch("http://127.0.0.1:5000/storages")
      .then(res => res.json())
      .then(data => setStorages(data.storages.map(s => ({
        id: s.StorageID,
        name: s.StorageName,
        address: s.StorageAddress,
        location: [s.StorageLat, s.StorageLong],
      }))))
      .catch(console.error);

    fetch("http://127.0.1:5000/catalogs")
      .then(res => res.json())
      .then(data => setCatalogs(data.catalogs.map(c => ({
        id: c.CatalogID,
        name: c.CatalogName,
      }))))
      .catch(console.error);
  }, []);

  // Add a new row
  const addRow = () => {
    setRows([
      ...rows,
      {
        id: Date.now() + Math.random(),
        customerId: '',
        customerName: '',
        category: '',
        quantity: '',
        weight: '',
        storageId: '',
        storageName: ''
      }
    ]);
    setSearchTerms([...searchTerms, { customer: '', storage: '' }]);
    setCustomerSuggestions([...customerSuggestions, []]);
    setStorageSuggestions([...storageSuggestions, []]);
  };

  // Add one customer row on mount
  useEffect(() => {
    if (rows.length === 0) addRow();
  }, []);

  // Remove a row
  const removeRow = (idx) => {
    setRows(rows.filter((_, i) => i !== idx));
    setSearchTerms(searchTerms.filter((_, i) => i !== idx));
    setCustomerSuggestions(customerSuggestions.filter((_, i) => i !== idx));
    setStorageSuggestions(storageSuggestions.filter((_, i) => i !== idx));
  };

  // Update a field in a row
  const updateRow = (idx, field, value) => {
    setRows(rows.map((row, i) =>
      i === idx ? { ...row, [field]: value } : row
    ));
  };

  // Handle live search for customer
  const handleCustomerSearch = (idx, value) => {
    setSearchTerms(searchTerms.map((term, i) =>
      i === idx ? { ...term, customer: value } : term
    ));
    const suggestions = value.trim()
      ? customers.filter(c =>
          c.name.toLowerCase().includes(value.toLowerCase()) &&
          !rows.some((row, i) => i !== idx && row.customerId === c.id)
        ).slice(0, 5)
      : [];
    setCustomerSuggestions(customerSuggestions.map((s, i) =>
      i === idx ? suggestions : s
    ));
    if (value === '') {
      updateRow(idx, 'customerName', '');
      updateRow(idx, 'customerId', '');
    } else {
      updateRow(idx, 'customerName', value);
      updateRow(idx, 'customerId', '');
    }
  };

  // Select a customer from suggestions
  const selectCustomer = (idx, customer) => {
    updateRow(idx, 'customerId', customer.id);
    updateRow(idx, 'customerName', customer.name);
    setCustomerSuggestions(customerSuggestions.map((s, i) =>
      i === idx ? [] : s
    ));
    setSearchTerms(searchTerms.map((term, i) =>
      i === idx ? { ...term, customer: undefined } : term
    ));
  };

  // Handle live search for storage
  const handleStorageSearch = (idx, value) => {
    setSearchTerms(searchTerms.map((term, i) =>
      i === idx ? { ...term, storage: value } : term
    ));
    const suggestions = value.trim()
      ? storages.filter(s =>
          s.name.toLowerCase().includes(value.toLowerCase()) &&
          !rows.some((row, i) => i !== idx && row.storageId === s.id)
        ).slice(0, 5)
      : [];
    setStorageSuggestions(storageSuggestions.map((s, i) =>
      i === idx ? suggestions : s
    ));
    if (value === '') {
      updateRow(idx, 'storageName', '');
      updateRow(idx, 'storageId', '');
    } else {
      updateRow(idx, 'storageName', value);
      updateRow(idx, 'storageId', '');
    }
  };

  // Select a storage from suggestions
  const selectStorage = (idx, storage) => {
    updateRow(idx, 'storageId', storage.id);
    updateRow(idx, 'storageName', storage.name);
    setStorageSuggestions(storageSuggestions.map((s, i) =>
      i === idx ? [] : s
    ));
    setSearchTerms(searchTerms.map((term, i) =>
      i === idx ? { ...term, storage: undefined } : term
    ));
  };

  // Close suggestions on outside click
  useEffect(() => {
    const onClickOutside = e => {
      suggestionRefs.current.forEach((ref, idx) => {
        if (ref && !ref.contains(e.target)) {
          setCustomerSuggestions(s => s.map((arr, i) => i === idx ? [] : arr));
          setStorageSuggestions(s => s.map((arr, i) => i === idx ? [] : arr));
        }
      });
    };
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, [suggestionRefs, customerSuggestions, storageSuggestions]);

  return (
    <div className="container">
      <header className="header">
        <div className="header-left">
          <h1 className="route-name">Assign Truck</h1>
          {/* <p className="route-desc">Assign truck to customer</p> */}
        </div>
        <div className="header-right">
          <button className="btn add-row-btn" onClick={addRow}>+ Add</button>
        </div>
      </header>
      <div className="content">
        <main className="main-area">

          <div className="table">
            {rows.map((row, idx) => (
              <div className="customer-box" key={row.id}>
                <div className="customer-header-row">
                  <label className="customer-label">customer:</label>
                  <div className="customer-input-cell">
                    <div className="suggestion-wrapper">
                      <input
                        className="input customer-input"
                        placeholder="Type to search customers…"
                        value={searchTerms[idx]?.customer !== undefined
                          ? searchTerms[idx].customer
                          : row.customerName}
                        onChange={e => handleCustomerSearch(idx, e.target.value)}
                      />
                      {customerSuggestions[idx]?.length > 0 && (
                        <ul className="suggestions-list">
                          {customerSuggestions[idx].map(c => (
                            <li key={c.id} onClick={() => selectCustomer(idx, c)}>
                              {c.name} — {c.address}
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>
                  </div>
                  <button className="btn remove-btn customer-remove-btn" onClick={() => removeRow(idx)}>×</button>
                </div>
                <div className="product-table">
                  <div className="product-table-header">
                    <span>product</span>
                    <span>category</span>
                    <span>quantity</span>
                    <span>weight</span>
                    <span>storage</span>
                    <span></span>
                    <button className="btn add-row-btn product-add-btn" onClick={() => addRow()}>+ add product</button>
                  </div>
                  <div className="table-row">
                    <div className="table-cell">
                      <input
                        className="input product-input"
                        placeholder="Product"
                        value={row.product || ''}
                        onChange={e => updateRow(idx, 'product', e.target.value)}
                      />
                    </div>
                    <div className="table-cell">
                      <select
                        className="input category-input"
                        value={row.category}
                        onChange={e => updateRow(idx, 'category', e.target.value)}
                      >
                        <option value="">Select Category</option>
                        {categories.map(c => (
                          <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                      </select>
                    </div>
                    <div className="table-cell">
                      <input
                        className="input quantity-input"
                        type="string"
                        placeholder="Quantity"
                        value={row.quantity}
                        onChange={e => updateRow(idx, 'quantity', e.target.value)}
                      />
                    </div>
                    <div className="table-cell">
                      <input
                        className="input weight-input"
                        type="string"
                        placeholder="Weight"
                        value={row.weight}
                        onChange={e => updateRow(idx, 'weight', e.target.value)}
                      />
                    </div>
                    <div className="table-cell">
                      <div className="suggestion-wrapper">
                        <input
                          className="input storage-input"
                          placeholder="Type to search storages…"
                          value={searchTerms[idx]?.storage !== undefined
                            ? searchTerms[idx].storage
                            : row.storageName}
                          onChange={e => handleStorageSearch(idx, e.target.value)}
                        />
                        {storageSuggestions[idx]?.length > 0 && (
                          <ul className="suggestions-list">
                            {storageSuggestions[idx].map(s => (
                              <li key={s.id} onClick={() => selectStorage(idx, s)}>
                                {s.name} — {s.address}
                              </li>
                            ))}
                          </ul>
                        )}
                      </div>
                    </div>
                    <div className="remove-btn-cell">
                      <button className="btn remove-btn" onClick={() => removeRow(idx)}>×</button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
          <div className="submit-btn-row">
            <button className="btn submit-btn" onClick={() => console.log(rows)}>Submit</button>
          </div>
        </main>
      </div>
    </div>
  );
}

export default App;
